      const timeout=setTimeout(()=>controller.abort(),timeoutMs);
      try{const response = await fetch(path, {...requestOptions, headers,signal:controller.signal});const data = await response.json().catch(() => ({}));if (!response.ok){const error=new Error(data.error||`HTTP ${response.status}`);error.httpStatus=response.status;error.data=data;throw error;}const recovered=this.connectionState==='reconnecting';this.connectionState='connected';if(recovered&&this.status==='Agent Host 连接中断，正在自动重连…')this.status='Agent Host 已重新连接，后台状态已同步';return data;}
      catch(error){if(callerSignal?.aborted)throw error;if(error.httpStatus){this.connectionState='connected';throw error;}if(!deferConnectionFailure){this.connectionState='reconnecting';this.status='Agent Host 连接中断，正在自动重连…';}if(error.name==='AbortError')throw new Error('本地后端响应超时');throw error;}finally{clearTimeout(timeout);callerSignal?.removeEventListener('abort',abortFromCaller);}
