    async providerChanged() { this.ensureModels();this.scheduleContextPreview(80); await this.saveSettings(); },
    async modelChanged(){this.revalidateAttachments();this.scheduleContextPreview(80);await this.saveSettings();},
    async saveSettings() { try { await this.api('/api/settings', {method:'POST', body:this.settings}); } catch (_) {} },
