    applyAppearance(){const requested=this.settings.theme||'system',dark=window.matchMedia?.('(prefers-color-scheme: dark)').matches,skin=this.activeSkin;document.documentElement.dataset.edition=this.isOpenSource?'opensource':'local';document.documentElement.dataset.theme=requested==='system'?(dark?'dark':'light'):requested;document.documentElement.dataset.themeMode=requested;document.documentElement.dataset.skin=skin?.compatibility==='codex'?'codex':(this.settings.skin||'fusion');document.documentElement.dataset.skinId=this.settings.skin||'fusion';let link=document.getElementById('agent-skin-css');if(skin?.css){if(!link){link=document.createElement('link');link.id='agent-skin-css';link.rel='stylesheet';document.head.appendChild(link);}link.href=this.skinAssetUrl(skin,skin.css)+'?v='+encodeURIComponent(skin.id);}else if(link)link.remove();},
    async setAppearance(key,value){this.settings[key]=value;this.applyAppearance();await this.saveSettings();},
    skinAssetUrl(skin,file){return `/api/workbench/skins/asset/${encodeURIComponent(skin.id)}/${String(file||'').split('/').map(encodeURIComponent).join('/')}`;},
