    async importSkin(){if(!confirm('导入第三方皮肤：发布版需要可信签名；development 开发包没有发布者身份保证，仅导入你信任的来源。继续？'))return;try{const skin=await this.api('/api/workbench/skins/import',{method:'POST',body:{}});if(skin.cancelled)return;await this.loadSkins();this.settings.skin=skin.id;this.applyAppearance();await this.saveSettings();this.status=`已导入并启用皮肤：${skin.name}`;}catch(error){this.status='导入皮肤失败：'+error.message;}},
    async deleteSkin(item){if(!item?.imported||!confirm(`删除皮肤“${item.name}”？\n\n只删除工作台保存的皮肤副本，不影响原始文件。`))return;try{await this.api('/api/workbench/skins/delete',{method:'POST',body:{id:item.id}});if(this.settings.skin===item.id)this.settings.skin='fusion';await this.loadSkins();this.applyAppearance();await this.saveSettings();this.status='皮肤已删除';}catch(error){this.status='删除皮肤失败：'+error.message;}},
