    async changeTerminalShell(){if(this.terminalId){await this.api('/api/workbench/terminal/stop',{method:'POST',body:{id:this.terminalId}}).catch(()=>{});this.terminalId='';this.terminalActiveShell='';}await this.ensureTerminal();},
